DROP PROCEDURE IF EXISTS migrate_105_finishing_recipe_creator;
CREATE PROCEDURE migrate_105_finishing_recipe_creator() BEGIN IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'finishing_recipes' AND COLUMN_NAME = 'created_by') THEN ALTER TABLE finishing_recipes ADD COLUMN created_by CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL AFTER swatch_image; END IF; ALTER TABLE finishing_recipes MODIFY COLUMN created_by CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL; IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'finishing_recipes' AND COLUMN_NAME = 'created_by' AND REFERENCED_TABLE_NAME = 'users') THEN ALTER TABLE finishing_recipes ADD CONSTRAINT fk_finishing_recipes_created_by FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE CASCADE; END IF; END;
CALL migrate_105_finishing_recipe_creator();
DROP PROCEDURE migrate_105_finishing_recipe_creator;
